def signal(obs):
    st = obs.state
    prev = st.get('p', {})
    out = {}
    try:
        ab = obs.last('A', 'bid'); aa = obs.last('A', 'ask')
        bb = obs.last('B', 'bid'); ba = obs.last('B', 'ask')
        cb = obs.last('C', 'bid'); ca = obs.last('C', 'ask')
        ib = obs.last('IDX', 'bid'); ia = obs.last('IDX', 'ask')
        vals = (ab, aa, bb, ba, cb, ca, ib, ia)
        ok = True
        for v in vals:
            if v != v or v <= 0:
                ok = False
                break
        if not ok:
            raise ValueError('nan book')
        bask_ask = 0.3333 * aa + 0.6667 * ba + 0.1667 * ca
        bask_bid = 0.3333 * ab + 0.6667 * bb + 0.1667 * cb
        p_sell = ib - bask_ask
        p_buy = bask_bid - ia
    except Exception:
        # keep previous targets on bad data
        return dict(prev) if prev else {}
    # hysteresis thresholds (cents): enter when clearly profitable, exit near zero
    ENTER = 2.0
    EXIT = -4.0
    cur = st.get('dir', 0)
    if cur == 0:
        if p_sell > ENTER:
            cur = -1
        elif p_buy > ENTER:
            cur = 1
    elif cur == -1:
        # short IDX / long basket; exit when edge gone (p_sell back below EXIT) or other side appears
        if p_buy > ENTER:
            cur = 1
        elif p_sell < EXIT:
            cur = 0
    else:
        if p_sell > ENTER:
            cur = -1
        elif p_buy < EXIT:
            cur = 0
    st['dir'] = cur
    if cur == -1:
        out['IDX'] = -0.8
        out['A'] = 0.2667
        out['B'] = 0.5333
        out['C'] = 0.1333
    elif cur == 1:
        out['IDX'] = 0.8
        out['A'] = -0.2667
        out['B'] = -0.5333
        out['C'] = -0.1333
    else:
        out['IDX'] = 0.0
        out['A'] = 0.0
        out['B'] = 0.0
        out['C'] = 0.0
    out['A.X'] = 0.0
    out['B.X'] = 0.0
    out['C.X'] = 0.0
    # smooth toward target to respect 2 lots/step (signal every 10 steps allows 20 lots, so direct is fine)
    st['p'] = dict(out)
    return out

