def signal(obs):
    window = 200
    # gather history for fair value
    try:
        a_hist = obs.hist('A', 'mid', window + 5)
        b_hist = obs.hist('B', 'mid', window + 5)
        c_hist = obs.hist('C', 'mid', window + 5)
        idx_hist = obs.hist('IDX', 'mid', window + 5)
    except Exception:
        return {}
    if len(a_hist) < window + 1 or len(b_hist) < window + 1 or len(c_hist) < window + 1 or len(idx_hist) < window + 1:
        return {}
    a = np.array(a_hist, dtype=float)
    b = np.array(b_hist, dtype=float)
    c = np.array(c_hist, dtype=float)
    idx = np.array(idx_hist, dtype=float)
    # compute fair value series
    fair = 0.3333 * a + 0.6667 * b + 0.1667 * c
    diff = idx - fair
    # use recent window for stats
    recent = diff[-window:]
    # remove nan
    recent_valid = recent[~np.isnan(recent)]
    if recent_valid.size < window // 2:
        return {}
    mean = float(np.nanmean(recent_valid))
    std = float(np.nanstd(recent_valid))
    if std == 0 or np.isnan(std) or np.isnan(mean):
        return {}
    cur_diff = float(diff[-1])
    if np.isnan(cur_diff):
        return {}
    z = (cur_diff - mean) / std
    # scale target, cap at +-0.8
    target_mag = 0.3 * z
    if target_mag > 0.8:
        target_mag = 0.8
    elif target_mag < -0.8:
        target_mag = -0.8
    # avoid tiny signals
    if abs(target_mag) < 0.05:
        return {}
    targets = {}
    # if index overpriced (z>0) short index, long components
    targets['IDX'] = -target_mag
    # weight components by basket weights, normalize sum to ~target_mag
    targets['A'] = target_mag * 0.3333
    targets['B'] = target_mag * 0.6667
    targets['C'] = target_mag * 0.1667
    # clip to [-1,1]
    for k in list(targets.keys()):
        v = targets[k]
        if v > 1.0:
            targets[k] = 1.0
        elif v < -1.0:
            targets[k] = -1.0
    return targets

