    arr = obs.hist('C', 'mid', 60)
    if arr is None or len(arr) < 51:
        return {}
    cur = arr[-1]
    prev50 = arr[-51]
    # NaN check
    if cur != cur or prev50 != prev50:
        return {}
    mom = cur - prev50
    prev_tar = s.get('tar', 0)
    tar = prev_tar
    if mom > 10:
        tar = 1
    elif mom < -10:
        tar = -1
    else:
        if prev_tar == 1 and mom < 3:
            if mom < -10:
                tar = -1
            else:
                tar = 0
        elif prev_tar == -1 and mom > -3:
            if mom > 10:
                tar = 1
            else:
                tar = 0
        elif prev_tar == 0:
            tar = 0
    s['tar'] = tar
    if tar == 0:
        return {'C': 0.0}
    return {'C': float(tar)}

def signal(obs):
    s = obs.state
    # price momentum 50
    arr_mid = obs.hist('C','mid',60)
    arr_sv = obs.hist('C','signed_volume',20)
    if arr_mid is None or len(arr_mid) < 51:
        return {}
    if arr_sv is None or len(arr_sv) < 10:
        return {}
    cur = arr_mid[-1]
    prev50 = arr_mid[-51]
    if cur != cur or prev50 != prev50:
        return {}
    mom = cur - prev50
    # signed volume sum last 10
    sv_win = arr_sv[-10:]
    # handle NaN
    sv_sum = 0.0
    cnt = 0
    for x in sv_win:
        if x == x:  # not NaN
            sv_sum += x
            cnt += 1
    if cnt < 5:
        return {}
    prev = s.get('tar', 0)
    tar = prev
    # entry requires both momentum and flow agreement
    if mom > 10 and sv_sum > 2:
        tar = 1
    elif mom < -10 and sv_sum < -2:
        tar = -1
    else:
        # hysteresis exit
        if prev == 1:
            if mom < 3 or sv_sum < -1:
                # if strong opposite signal, flip directly
                if mom < -10 and sv_sum < -2:
                    tar = -1
                else:
                    tar = 0
        elif prev == -1:
            if mom > -3 or sv_sum > 1:
                if mom > 10 and sv_sum > 2:
                    tar = 1
                else:
                    tar = 0
        else:
            tar = 0
            # allow entry already handled, else stay flat
            if mom > 10 and sv_sum > 2:
                tar = 1
            elif mom < -10 and sv_sum < -2:
                tar = -1
    s['tar'] = tar
    if tar == 0:
        return {'C': 0.0}
    return {'C': float(tar)}

def signal(obs):
    st=obs.state
    if 'ema' not in st:
        st['ema']={}
    targets={}
    for asset in ['A','C','IDX','A.X','C.X']:
        m=obs.hist(asset,'mid',80)
        if m is None or len(m)<80:
            continue
        if np.isnan(m[-1]) or np.isnan(m[0]):
            continue
        past=m[-1]-m[-50]
        diffs=np.diff(m[-50:])
        vol=np.nanstd(diffs)
        if vol==0 or np.isnan(vol):
            continue
        vol50=vol*np.sqrt(50)
        if vol50==0:
            continue
        score=past/vol50
        prev=st['ema'].get(asset, score)
        ema=0.9*prev+0.1*score
        st['ema'][asset]=ema
        sig=np.tanh(ema*1.2)
        if abs(sig)<0.2:
            sig=0
        targets[asset]=float(np.clip(sig*0.9,-1,1))
    try:
        mA=obs.last('A','mid'); mB=obs.last('B','mid'); mC=obs.last('C','mid'); mIDX=obs.last('IDX','mid')
        if not any(np.isnan(x) for x in [mA,mB,mC,mIDX]):
            basket=0.3333*mA+0.6667*mB+0.1667*mC
            mis=mIDX-basket
            z=mis/38.0
            arb_scale=0.4
            arb_sig=np.tanh(z)*arb_scale
            if 'IDX' in targets:
                targets['IDX']=float(np.clip(targets['IDX'] - arb_sig, -1, 1))
            else:
                targets['IDX']=float(np.clip(-arb_sig,-1,1))
            for asset,w in [('A',0.3333),('B',0.6667),('C',0.1667)]:
                add=arb_sig*w*1.5
                if asset in targets:
                    targets[asset]=float(np.clip(targets[asset]+add,-1,1))
                else:
                    if abs(add)>0.08:
                        targets[asset]=float(np.clip(add,-1,1))
                xv=asset+'.X'
                if xv in targets:
                    targets[xv]=float(np.clip(targets[xv]+add,-1,1))
    except:
        pass
    return targets

