def signal(obs):
    st=obs.state
    if 'ema' not in st:
        st['ema']={}
        st['mis']=[]
    targets={}
    for asset in ['A','A.X','C','C.X']:
        m=obs.hist(asset,'mid',60)
        if m is None or len(m)<60 or np.isnan(m[-1]):
            continue
        look=30 if asset in ('A','A.X') else 20
        past=m[-1]-m[-1-look]
        vol=np.nanstd(np.diff(m[-40:]))
        if vol==0 or np.isnan(vol):
            continue
        score=past/(vol*np.sqrt(look)+1e-9)
        prev=st['ema'].get(asset, score)
        ema=0.9*prev+0.1*score
        st['ema'][asset]=ema
        sig=np.tanh(ema*1.1)
        if abs(sig)<0.2:
            sig=0
        targets[asset]=float(np.clip(sig*0.95,-1,1))
    try:
        mA=obs.last('A','mid'); mB=obs.last('B','mid'); mC=obs.last('C','mid'); mIDX=obs.last('IDX','mid')
        if not any(np.isnan(x) for x in [mA,mB,mC,mIDX]):
            basket=0.3333*mA+0.6667*mB+0.1667*mC
            mis=mIDX-basket
            hist=st['mis']
            hist.append(mis)
            if len(hist)>500:
                hist.pop(0)
            if len(hist)>=200:
                arr=np.array(hist)
                mean=np.nanmean(arr)
                std=np.nanstd(arr)
                if std<8:
