                mom = a2 - b2
            else:
                prev = obs.state.get(asset, 0)
                out[asset] = prev
                continue
        else:
            mom = (a1 - b1 + a2 - b2) / 2.0
        prev = obs.state.get(asset, 0)
        if mom > thr:
            cur = 1
        elif mom < -thr:
            cur = -1
        else:
            cur = prev
        out[asset] = cur
        obs.state[asset] = cur
        out[asset + '.X'] = 0
    out['IDX'] = 0
    return out

