def signal(obs):
    st=obs.state
    if 'ema' not in st:
        st['ema']={}
    targets={}
    # momentum only on zero-fee venues + IDX
    for asset in ['A','B','C','IDX']:
        m=obs.hist(asset,'mid',80)
        if m is None or len(m)<80:
            continue
        if np.isnan(m[-1]) or np.isnan(m[0]):
            continue
        past=m[-1]-m[-50]
        diffs=np.diff(m[-50:])
        vol=np.nanstd(diffs)
        if vol==0 or np.isnan(vol):
            continue
        vol50=vol*np.sqrt(50)+1e-9
        score=past/vol50
        prev=st['ema'].get(asset, score)
        ema=0.88*prev+0.12*score
        st['ema'][asset]=ema
        sig=np.tanh(ema*0.9)
        # higher threshold to cut whipsaw
        if abs(sig)<0.35:
            sig=0
        # long bias slightly: boost positive
        if sig>0:
            sig*=1.0
        else:
            sig*=0.7
        scale=0.7 if asset!='IDX' else 0.45
        targets[asset]=float(np.clip(sig*scale,-1,1))
        # keep .X flat to avoid 3bps fee
        targets[asset+'.X']=0.0
    # small IDX-basket arb only on large deviations to add hedge
    try:
        mA=obs.last('A','mid'); mB=obs.last('B','mid'); mC=obs.last('C','mid'); mIDX=obs.last('IDX','mid')
        if not any(np.isnan(x) for x in [mA,mB,mC,mIDX]):
            basket=0.3333*mA+0.6667*mB+0.1667*mC
            mis=mIDX-basket
            if abs(mis)>55:
                z=mis/32.0
                arb=np.tanh(z)*0.6
                # adjust
                cur=targets.get('IDX',0)
                targets['IDX']=float(np.clip(cur - arb*0.7,-1,1))
                for a,w in [('A',0.3333),('B',0.6667),('C',0.1667)]:
                    cur2=targets.get(a,0)
                    targets[a]=float(np.clip(cur2 + arb*w*0.7,-1,1))
    except:
        pass
    return targets

def signal(obs):
    targets={}
    # mean reversion on C only, zero fee venue
    m=obs.hist('C','mid',10)
    if m is not None and len(m)>=5 and not np.isnan(m[-1]):
        ret=m[-1]-m[-2]
        vol=np.nanstd(np.diff(m[-5:]))+1e-9
        if not np.isnan(vol) and vol>0:
            z=ret/vol
            sig=np.tanh(z*0.8)*0.6
            # fade: negative
            targets['C']=float(np.clip(-sig,-1,1))
            targets['C.X']=0.0
    # keep others flat
    for a in ['A','A.X','B','B.X','IDX']:
        if a not in targets:
            targets[a]=0.0
    return targets

